    {'regulation_id': 'STD-JGJ-276-2012-6-1-1', 'scene_types': ['LIFTING_OPERATIONS'], 'standard_name': '建筑施工起重吊装工程安全技术规范', 'standard_code': 'JGJ 276-2012', 'article': '第6.1.1条', 'clause_text': '钢构件必须具有制造厂出厂产品质量检查报告，结构安装单位应根据构件性质分类，进行复检。', 'source_url': 'http://www.greatchinaca.com/web/upload/at/file/20190326/1553579705574474pB5E.pdf', 'sha256': '496344233c0245b71f9165c96a53a2d984311af1216b11a4f0bae2b6f05ca27f', 'method': 'pdf', 'fetched_at': '2026-10-26 17:00:27', 'cross_checked': True, 'cross_check_note': '与规则包共同覆盖的 1 条中 1 条条文一致（100%），据此判定抓取文本可用'},
    {'regulation_id': 'STD-JGJ-276-2012-6-1-2', 'scene_types': ['LIFTING_OPERATIONS'], 'standard_name': '建筑施工起重吊装工程安全技术规范', 'standard_code': 'JGJ 276-2012', 'article': '第6.1.2条', 'clause_text': '预检钢构件的计量标准、计量工具和质量标准必须统一。', 'source_url': 'http://www.greatchinaca.com/web/upload/at/file/20190326/1553579705574474pB5E.pdf', 'sha256': '496344233c0245b71f9165c96a53a2d984311af1216b11a4f0bae2b6f05ca27f', 'method': 'pdf', 'fetched_at': '2026-10-26 17:00:27', 'cross_checked': True, 'cross_check_note': '与规则包共同覆盖的 1 条中 1 条条文一致（100%），据此判定抓取文本可用'},
    {'regulation_id': 'STD-JGJ-276-2012-6-1-3', 'scene_types': ['LIFTING_OPERATIONS'], 'standard_name': '建筑施工起重吊装工程安全技术规范', 'standard_code': 'JGJ 276-2012', 'article': '第6.1.3条', 'clause_text': '钢构件应按照规定的吊装顺序配套供应，装卸时，装卸机械不得靠近基坑行走。', 'source_url': 'http://www.greatchinaca.com/web/upload/at/file/20190326/1553579705574474pB5E.pdf', 'sha256': '496344233c0245b71f9165c96a53a2d984311af1216b11a4f0bae2b6f05ca27f', 'method': 'pdf', 'fetched_at': '2026-10-26 17:00:27', 'cross_checked': True, 'cross_check_note': '与规则包共同覆盖的 1 条中 1 条条文一致（100%），据此判定抓取文本可用'},
